-- PT107-S4-Q24. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT107-S4-Q24$batch11$ AND q.stimulus=$batch11$Medical researcher: As expected, records covering the last four years of ten major hospitals indicate that babies born prematurely were more likely to have low birth weights and to suffer from health problems than were babies not born prematurely. These records also indicate that mothers who had received adequate prenatal care were less likely to have low birth weight babies than were mothers who had received inadequate prenatal care. Adequate prenatal care, therefore, significantly decreases the risk of low birth weight babies.$batch11$ AND q.prompt=$batch11$Which one of the following, if true, most weakens the medical researcher's argument?$batch11$ AND q.correct_choice=$batch11$B$batch11$) THEN RAISE EXCEPTION 'Question changed: PT107-S4-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT107-S4-Q24$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S4-Q24'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT107-S4-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Adequate prenatal care significantly lowers the risk of low birth weight.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Premature babies were more likely to have low birth weight. Mothers with adequate prenatal care were less likely to have low-birth-weight babies.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$This is a correlation between care records and birth weight. If the records are skewed, the correlation could be built in. Premature babies tend to have low birth weight. If mothers of premature babies get labeled as having inadequate care by default, the link would appear even if care made no difference.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Find a flaw in how the records link care to birth weight.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT107-S4-Q24$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Many babies of inadequate-care mothers having normal weight is consistent with care lowering the risk.$batch11$), ($batch11$B$batch11$, $batch11$Mothers of premature babies get marked as inadequate care whenever their records are missing. Since premature babies tend to be underweight, the records tie inadequate care to low weight automatically.$batch11$), ($batch11$C$batch11$, $batch11$How low-weight babies are classified as premature doesn't affect the link between care and weight.$batch11$), ($batch11$D$batch11$, $batch11$Some exceptions don't undercut a claim about lowered risk.$batch11$), ($batch11$E$batch11$, $batch11$If care reduces premature births, and premature babies tend to be underweight, care plausibly does lower the risk.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT107-S4-Q24$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
